Tool response:
Tool: reschedule_appointment
Description: Update the datetime of an existing appointment to a new date and time. 
The appointment must be currently scheduled and belong to the authenticated user.
Parameters:
    {
      "type": "object",
      "properties": {
        "appointment_id": {
          "type": "integer",
          "description": "Internal ID of the appointment to reschedule",
          "title": "Appointment Id"
        },
        "new_datetime": {
          "type": "string",
          "title": "New Datetime"
        }
      },
      "required": [
        "appointment_id",
        "new_datetime"
      ]
    }
